  "srch.morphNote": { uk: "Морфології немає: слово обрізається до основи, тому «тривожність» і «тривожності» — те саме, а «тривога» — вже інше", ru: "Морфологии нет: слово обрезается до основы, поэтому «тревожность» и «тревожности» — одно, а «тревога» — уже другое" },
