  "hint.gotIt": { uk: "Зрозуміло", ru: "Понятно" },
  "hint.stens": { uk: "Стен — це бал за десятибальною шкалою з середнім 5,5. «Високий стен» означає «вище, ніж у більшості вибірки», а не «погано»: що саме означає високий бал, залежить від шкали.", ru: "Стен — это балл по десятибалльной шкале со средним 5,5. «Высокий стен» означает «выше, чем у большинства выборки», а не «плохо»: что именно значит высокий балл, зависит от шкалы." },
  "hint.caseStatus": { uk: "«Підтверджено» означає, що ризик є і з ним працюють. «Потребує спостереження» — ризик не знято, але дій зараз не потрібно. «Без результату» — не вдалося зв’язатися або людина вибула; це теж результат розбору, а не порожнє поле.", ru: "«Подтверждён» означает, что риск есть и с ним работают. «Требует наблюдения» — риск не снят, но действий сейчас не нужно. «Без исхода» — не удалось связаться или человек выбыл; это тоже результат разбора, а не пустое поле." },
  "hint.rci": { uk: "Достовірність зміни відповідає на питання «це справжня зміна чи шум вимірювання». Різниця в кілька балів між замірами може повністю вкладатися в похибку методики — тоді говорити про поліпшення зарано.", ru: "Достоверность изменения отвечает на вопрос «это настоящее изменение или шум измерения». Разница в несколько баллов между замерами может целиком укладываться в ошибку методики — тогда говорить об улучшении рано." },
